-- =============================================================================
-- The program's videos, as knowledge for the bot: transcripts in 300–500-word
-- chunks, each tied to its video (and so to its opening day). The embeddings
-- are added by the bot-jobs function. Run AFTER run_whatsapp_bot_3.sql.
-- Replaces the video chunks loaded before. Safe to run more than once.
-- =============================================================================
BEGIN;
DELETE FROM public.bot_knowledge WHERE source = 'video';
INSERT INTO public.bot_knowledge (source, content_id, title, unlock_day, chunk_index, text)
SELECT 'video', c.id, COALESCE(c.title, $k$סרטון: ברוכים הבאים$k$), COALESCE(c.unlock_day, 1), 0, $k$אהלן חבר'ה, אני יאיר וברוכים הבאים לתוכנית חטוב בלי תפריט. אני ממש ממש שמח שאתם כאן ולפני שאני אתחיל להגיד לכם איך ומה אנחנו הולכים לעשות ואיך בדיוק התוכנית הזאת הולכת לעבוד, חשוב לי להדגיש אתכם משהו מאוד מאוד חשוב וקריטי להצלחה שלכם בתהליך הזה. אז אני יודע שחלקכם ניסיתם תוכניות כאלו ואחרות, דיאטות, תפריטים, אימונים, כל מיני דברים כאלו ואחרים. אני רוצה שמעכשיו תעשו את הסוויץ' הזה במוח שלכם ותמחקו את כל מה שאתם יודעים על תפריטים, על אימונים, על דיאטות, על כל דבר כזה או אחר שניסיתם ותיכנסו ותתמקדו אך ורק בהרגלים ובדברים שאנחנו אומרים לכם בתהליך. ממש תעשו סוויץ' למוח, כאילו שכחתם את כל מה שהיה לכם לפני ועכשיו אתם יוצאים לדרך חדשה, לבעצם אורח חיים חדש שאנחנו בעצם נבנה לכם. חשוב מאוד שתעשו את זה כבר מההתחלה כי זה בסוף מה שישפיע על התוצאה שלכם בתהליך הזה. אז עכשיו בואו נתחיל לדבר אני קודם כל אציג את עצמי אני יאיר מניח שאתם כבר מכירים אותי מהסרטונים מהרשתות וביחד עם השותף שלי בניתי את התוכנית הזאת שנקראת חטוב בלי תפריט שזה בעצם הדרך שלכם או נקרא לזה יותר מפת הדרכים שלכם לאורח חיים בריא. איך התוכנית הזאת בעצם תעבוד? אז בעצם התוכנית שלנו בנויה מכמה חלקים ממש כל שבוע או שבועיים או שלוש אתם תקבלו עוד שיפורים או הרגלים או דברים שאנחנו נרצה שתעשו כדי בסוף להתחיל להתקדם. בחלק הראשון שזה החלק שאתם נמצאים בו עכשיו אתם הולכים לקבל ממש כל שבוע סרטון שלי והסבר ואפילו גם מדריכים שאני אעבור עליהם עוד מעט בהמשך שיסבירו לכם איך לעשות את ההרגלים ואת הדברים שאנחנו נרצה שתעשו בתהליך הזה או בשבוע הזה בצורה הכי טובה פשוט הסבר פשוט של מה אתם צריכים לעשות באותו שבוע מדהים אז זה הדבר הראשון שאתם צריכים להבין דבר שני זה אני רוצה לעבור עכשיו על כמה מדריכים שהולכים להתווסף אליכם כבר עכשיו המדריך הראשון זה איך להישקל בצורה טובה כל שבוע אתם בעצם תצטרכו להישקל מחדש ביום שישי בבוקר חשוב מאוד שתזכרו את זה וגם יש לנו עכשיו מדריך שיתווסף אליכם כמו שאמרתי שעליו תצטרכו גם לעבור יש שם את הכללים לאיך להישקל מה עושים עם איזה בגדים באיזה זמן נשקלים כל הדברים האלה כתובים במדריך הזה תעברו עליו הוא מאוד מאוד חשוב כי ככה אנחנו רוצים שתישקלו מעכשיו כל שבוע דבר שני שתקבלו השבוע זה הספר נשנושים שלנו חלק מכם כבר מכירים אותו אבל יהיה לכם אותו באופן זמין יותר באפליקציה בכפתור שפשוט תלחצו עליו ותוכלו להיכנס אליו. בספר הזה בעצם יהיה המון המון מתכונים שאנחנו פיתחנו לאורך השנים וכתבנו לכם אותם שם בצורה מסודרת וזה מתכונים שיש בהם קודם כל הרבה חלבון, הם דלי קלוריות הרבה יותר בריאים הרבה יותר משביעים מאוד יכולים לעזור לכם בתהליך ואם תלכו ותעשו אותם מדהים וזה שלכם בעצם. דבר שלישי שתקבלו השבוע זה מדריך אני חולה מה עושים זה לחס וחלילה אם אתם חולים לא מרגישים טוב עדיין תדעו איך למקסם את הזמן שלכם בעצם בתקופה הזאת שאתם לא מרגישים טוב וכן להוציא את המקסימום מהדבר הזה. אז תעברו עליו הוא ממש ממש חשוב כל פעם שתהיו חולים פשוט תפתחו אותו ולאט לאט אתם כבר תזכרו מה עושים שזה לא יקרה הרבה בעזרת השם. וזהו חבר'ה זה בעצם היה החלק הראשון של התהליך שלנו עכשיו ממש אתם תעברו לשבוע מספר אחת שם תקבלו כבר את ההרגלים החדשים שלכם לפני זה כמובן תעברו על המדריכים שאמרתי פה ויאללה אנחנו נתראה.$k$
FROM (SELECT 1) one LEFT JOIN LATERAL (
  SELECT id, title, unlock_day FROM public.program_content
  WHERE content_type = 'video' AND archived_at IS NULL AND title LIKE $k$ברוכים הבאים%$k$
  ORDER BY sort_order LIMIT 1) c ON true;
INSERT INTO public.bot_knowledge (source, content_id, title, unlock_day, chunk_index, text)
SELECT 'video', c.id, COALESCE(c.title, $k$סרטון: שבוע 1$k$), COALESCE(c.unlock_day, 1), 0, $k$אוקיי חבר'ה, שבוע מספר אחת, ברוכים הבאים. אנחנו מתחילים עכשיו להוסיף הרגלים בעצם חדשים לחיים שלכם. אז ההרגל הראשון שמתווסף לכם לחיים זה שתיית שתי כוסות מים לפני הארוחות הגדולות שלכם ושתיית כוס מים לפני הארוחה הקטנה שלכם. למה אנחנו בעצם עושים את הדבר הזה? כי שתיית מים לפני הארוחה גורמת לסור במוקדם. ברגע שאנחנו שותים שתי כוסות מים לפני הארוחה או כוס מים לפני נשנוש, הבטן שלנו מתמלאת ואנחנו מרגישים כבר הרבה יותר זביעים. להבדיל בין רעב לצמא וככה אנחנו יכולים למנוע את האכילה המופחדת שלנו, את האכילה משעמום או את הבולמוסים שיהיו לנו אחרי זה ולצאת מהארוחה הרבה יותר זביעים או מהארוחה הגדולה או מהארוחה הקטנה זה בעצם אותו דבר. עוד יתרון שיש לשתיית מים לפני הארוחה זה העלאת צריכת המים היומית שלנו. בסוף כל בן אדם צריך לשתות בין 2 ל-3 ליטר לפני הארוחה שזאת בעצם איזה מוצא ביום שלנו שקורית כל יום לפני הארוחה הקטנה או לפני הארוחה הגדולה, לנו הרבה יותר קל לבוא ולזכור לשתות מים. אנחנו לא נצטרך לחשוב על כל פעם מה אני לא שתיתי אז, לא שתיתי פה, אני יודע שכל ארוחה שתיתי 2 כוסות לפני הגדולה ואחת לפני הקטנה ואז אני גם זוכר ומרגיל את הגוף שלי לשתות הרבה יותר מים. תחשבו על זה רגע שאם יש לכם 4 ארוחות ביום, 2 קטנות ו2 גדולות ושתיתם לפני הגדולות 2 כוסות מים ולפני הקטנות כוס מים אחת אתם כבר בליטר וחצי ביום יום שלכם וזה בכלל לפני ששתיתם את כל שאר המים שאתם בעצם שותים ביום יום. חשוב מאוד שתבינו שבהתחלה אתם לא תמיד תזכרו את זה תמיד וזה בסדר גמור ככה לאט לאט בונים את ההרגל אבל הכי חשוב שתמשיכו ותתמידו וגם אם לא זכרתם פעם אחת הכל בסדר. ביום הבא אנחנו ממשיכים קדימה ולא מסתכלים אחורה כל עוד אתם ממשיכים ועושים את מה שאתם עושים אתם תגיעו בסוף לתוצאה ובסוף זה יבוא לכם כבר באופן אוטומטי אתם תרגישו את זה. ועכשיו להרגל השני שלנו שהוא הליכה של פעם אחת בשבוע. הליכה של בערך בין 20-30 דקות זאת הליכה טובה ולמה אנחנו בעצם עושים את זה כי קודם כל הליכה שורפת לנו קלוריות. אני בסוף רוצה להעלות את מספר הצעדים היומיים שלכם והליכה יכולה מאוד מאוד לעזור לזה ברגע שתתחילו להתרגל לזה ולילה אנחנו גם נעלה קצב ונעלה את מספר הצעדים אתם תראו שאתם תוכלו לשרוף הרבה יותר קלוריות במהלך היום וגם להכניס הרבה יותר וזה גם יעזור לכם בתהליך לשובע לכל מיני דברים אחרים.$k$
FROM (SELECT 1) one LEFT JOIN LATERAL (
  SELECT id, title, unlock_day FROM public.program_content
  WHERE content_type = 'video' AND archived_at IS NULL AND title LIKE $k$שבוע 1:%$k$
  ORDER BY sort_order LIMIT 1) c ON true;
INSERT INTO public.bot_knowledge (source, content_id, title, unlock_day, chunk_index, text)
SELECT 'video', c.id, COALESCE(c.title, $k$סרטון: שבוע 1$k$), COALESCE(c.unlock_day, 1), 1, $k$עוד יתרון מאוד מאוד גדול שיש להליכות זה הורדת הסטרס ידוע שהליכה מורידה סטרס מורידה לחץ למה אני בעצם רוצה שתעשו את זה כי בסוף אנחנו חיים במדינת ישראל ויש המון המון לחץ באוויר ולחץ הרבה פעמים יכול לבוא ולפגוע לנו בתהליך ירידה במשקל כי לחץ וסטרס גורם לקורטיזול גבוה מה שגורם לנו לנפיחות וגם בסוף גורם לנו לאכול סתם בלי שאנחנו בכלל שמים לב אנחנו פתאום לוקחים את השוקולד הזה ואת החטיף הזה ופשוט מכניסים לפה כי אנחנו בלחץ. ברגע שתורידו את סף הלחץ שלכם עם הליכה מרגיעה במהלך היום יהיה לכם הרבה יותר קל להתמיד בתהליך הזה ומעבר לזה לשלוט במה שאתם אוכלים ומה שקורה לכם ביום יום בצלחת. ויתרון נוסף שיש בעצם להליכה זה שהוא מעלה לנו את קצב חילוף החומרים מה שגורם לתהליך שלנו להיות הרבה יותר קל. כי ברגע שיש לכם קצב חילוף חומרים גבוה אתם כל כל שורפים יותר קלוריות במנוחה גם אם עכשיו סתם תשבו וישב לידכם בן אדם שלא הולך או לא עושה פעילות גופנית אתם תשרפו יותר קלוריות ממנו במנוחה. דבר שני ברגע שאתם בתהליך ירידה במשקל או חיטוב אתם נמצאים בגירעון קלורי מה זה אומר שאתם בעצם מוציאים יותר קלוריות ממה שאתם מכניסים כתוצאה מכך קצב חילוף החומרים שלכם יורד באופן אוטומטי וברגע שאתם עושים את ההליכה הזאתי קצב חילוף החומרים שלכם במקום לרדת בתהליך הוא רק עולה עולה או נשאר באותו מאזן לפחות וזה דבר מאוד מאוד חשוב אז כבר עכשיו תסמנו באפליקציה איזה יום אתם בעצם עושים ותתמידו בו חשוב מאוד. עוד טיפ קטן שיכול לעזור לכם לשלב את ההליכה ביום יום שלכם זה למצוא איזשהו עוגן שכבר קורה לכם ביום יום שבעצם אחריו ישר אתם עושים את ההליכה. לדוגמה זה יכול להיות לדוגמה אח שאתם חוזרים מהעבודה ישר כשאתם חוזרים לצאת להליכה או לדוגמה אחרי הקפה בבוקר ישר לצאת להליכה איזשהו עוגן שכבר קורה לכם ביום יום פעולה שאתם כבר עושים וישר לאחריה להצמיד את ההליכה ככה יהיה לכם הרבה יותר קל לזכור את זה וזה כבר מה שדיברנו עליו מי שלא ראה את הסרטון של תקנות וצימוד הרגלים לכו תראו את זה זה נקרא בעצם צימוד הרגלים וזה בעצם לעבור ולעזור לעצמנו להתרגל לדבר הזה בצורה הרבה יותר קלה וזה בגדול חבר'ה זה השבוע מספר 1 תתחילו להתמיד בהרגלים שלכם יאללה נתראה בשבוע מספר 2$k$
FROM (SELECT 1) one LEFT JOIN LATERAL (
  SELECT id, title, unlock_day FROM public.program_content
  WHERE content_type = 'video' AND archived_at IS NULL AND title LIKE $k$שבוע 1:%$k$
  ORDER BY sort_order LIMIT 1) c ON true;
INSERT INTO public.bot_knowledge (source, content_id, title, unlock_day, chunk_index, text)
SELECT 'video', c.id, COALESCE(c.title, $k$סרטון: שבוע 2$k$), COALESCE(c.unlock_day, 8), 0, $k$אוקיי חבר'ה, ברוכים הבאים לשבוע מספר 2 ועכשיו אנחנו הולכים לצרף אליכם עוד כמה הרגלים לחיים שלכם. אז ההרגל הראשון שמצטרף אלינו זה להתחיל לאכול שלוש שעות לאחר הקימה שלכם ולהפסיק לאכול שעה לפני שאתם הולכים לישון. זה בעצם איזשהו לו"ז מסוים, איזשהו סדר לו"ז מסוים שאתם יודעים שבו אתם מתחילים לאכול ובו אתם מפסיקים לאכול. פשוט מאוד. למה אנחנו בעצם עושים את זה? קודם כל כשאנחנו קמים בבוקר, הגוף שלנו עדיין לא יתעורר. אנחנו עדיין לא רוצים ישר לבוא ולדחוף לו אוכל, כי אנחנו עדיין רוצים שהוא יבוא ויעורר את עצמו, שיהיה איזה ריסטארט במערכות, אנחנו רגע קמנו, אנחנו לא מעורפלים, לתת לו עכשיו משהו, להקל, זה לא יעבוד טוב, ותאמינו לי זה לא עושה טוב לגוף. עוד יתרון שיש לדבר הזה זה שברגע שאנחנו עושים צום ברמה כזאת או אחרת, האינסולין בגוף יורד, וזה מאוד עוזר לנו בתהליך ירידה במשקל שלנו. כי אינסולין זה משהו שהוא יגר שומן, וברגע שיש לכם אינסולין גבוה, הרבה יותר קשה לבוא ולהוריד באחוזי השומן, וכתוצאה מכך גם לרדת במשקל. ועכשיו אם רגע נעבור ללילה, למה אנחנו בעצם עוצרים שעה לפני שאנחנו הולכים לישון? כי קודם כל אנחנו נותנים לגוף שלנו מנוחה. אנחנו מכינים את הגוף שלנו שאנחנו בסוף הולכים לישון, לדוגמה אם עכשיו אתם תאכלו דקה לפני שאתם הולכים לישון מערכת העיכול שלכם עדיין עובדת והיא לא מוכנה רגע לישון ולכן יכול לצאת לכם הרבה פעמים שהם סתם משווים במיטה ולא מבינים למה אתם לא נרדמים. בגלל זה אנחנו כבר מכינים את הגוף שלנו לישון וכך אנחנו נמקסם את שעות השינה שלנו. וגם אם אתם חושבים שאתם גאונים והצלחתם לאכול דקה לפני שאתם הולכים לישון ולהירדם, עדיין חבר'ה השינה שלכם פשוט לא תהיה איכותית כי אתם לא תצליחו להגיע לשינה שהיא באמת עמוקה. ועכשיו להרגל השני שלנו שהוא מאוד מאוד חשוב וסופר דופר קריטי בתהליך שלנו זה שילוב ירקות בכל ארוחה שלכם. מה זה אומר מעכשיו אני רוצה שבכל ארוחה אתם תיקחו ירקות חתוכים, סלט, ירקות בתנור, כל דבר כזה או אחר ותשלבו את זה בארוחה שלכם. ממש כל ארוחה שאתם אוכלים. חבר'ה, ארוחה גדולה אני מדבר וגם מהארוחות הקטנות, אם תשלבו זה גם מאוד יכול לעזור, אבל בעיקר בארוחות הגדולות שאתם אוכלים, ארוחת צהריים, ארוחת ערב, ארוחת בוקר, בארוחות האלה תשלבו את הירקות, זה קריטי לתהליך.$k$
FROM (SELECT 1) one LEFT JOIN LATERAL (
  SELECT id, title, unlock_day FROM public.program_content
  WHERE content_type = 'video' AND archived_at IS NULL AND title LIKE $k$שבוע 2:%$k$
  ORDER BY sort_order LIMIT 1) c ON true;
INSERT INTO public.bot_knowledge (source, content_id, title, unlock_day, chunk_index, text)
SELECT 'video', c.id, COALESCE(c.title, $k$סרטון: שבוע 2$k$), COALESCE(c.unlock_day, 8), 1, $k$למה אני בעצם רוצה שתעשו את זה? כי ירקות זה מאכל עם הרבה מאוד נפח וגם מאוד דל קלורית. כלומר, אתם מרגישים שאתם מכניסים המון המון לגוף שלכם, וכתוצאה מכך אתם גם זביעים, אבל בתכלס המאכל הזה, הירק הזה, הגזר הזה, העגבנייה הזאתי היא לא הרבה קלוריות שאתם צורכים ביום-יום. זה הרבה בסוף נוזלים, זה הרבה בסוף סיבים תזונתיים, שלא מכילים הרבה קלוריות, אבל כן מאוד מאוד טובים לגוף שלנו, וכן מאוד יכולים לתרום לנו בתהליך ירידה במשקל, חיטוב, אורח חיים בריא. עוד יתרון שיש לירקות זה שיש בהם המון סיבים תזונתיים, כמו שאמרתי מקודם, מה שגורם לנו בסוף לעיכול הרבה יותר איטי, ולמיתון קפיצות הסוכר בדם, מה שמאוד יכול לעזור לנו בתהליך ירידה במשקל. איך אנחנו מכניסים לחיים שלנו את הירקות בצורה הכי הכי קלה וטובה? לחבר'ה שפה שלא אוכלים ירקות יותר מדי, אז פשוט קונים ירקות. הכי הכי פשוט שיש. חבר'ה, העלאת זמינות, תעזרו לעצמכם לבוא ולהשתנות. איך אנחנו עוזרים לעצמנו? שמים לנו את הירקות מול העיניים, ושמים הרבה מול העיניים. כלומר, ברגע שאני פותח את המקרר, אני רוצה לראות את הירקות שיש לי מול העיניים. ואם אתם רוצים לדעת איך עושים את זה בעבודה, הכי פשוט שיש. ישר כשאתם נכנסים לחדר אוכל, המחלקה הראשונה שאתם הולכים אליה, בופה או כל דבר כזה או אחר, זה קודם כל לבחור ירקות. אתם הולכים ובוחרים ירקות, ואז אחר כך ממשיכים לשער האוכל שאתם רוצים. ואם אין לכם חדר אוכל בעבודה, אז פשוט תדאגו יום לפני או בבוקר פשוט לחתוך לעצמכם ירקות או להביא ירקות בשקית, שיהיה לכם בעצם מה לאכול ביום-יום שאתם אוכלים בעצם את הארוחות הגדולות שלכם שגם בהם יהיו ירקות. פשוט מאוד תעלו את הזמינות ותכירו על עצמכם כמה שיותר כדי שלא יהיו פשלות או דברים בדרך. וגם כמובן אם אתם שכחתם או קרה משהו ולא הצלחתם לאכול ירקות בארוחה מסוימת, הכל בסדר. ממשיכים מהארוחה הבאה, ממשיכים להתקדם כל עוד אתם ממשיכים ועושים את זה, בסוף אתם תראו שזה יהפוך להרגל אוטומטי. אותו דבר אגב גם עם שלוש שעות מקסימום אכלתם שעתיים אחרי שקמתם הכל טוב. יום למחרת תמשיכו כרגיל זה בסוף הרגל שלוקח לו זמן להיכנס לחיים שלכם ואין מה לעשות. פשוט תמשיכו אתם בסוף תגיעו לזה. זה בגדול לכל חבר'ה לשבוע מספר 2 תתחילו ליישם נתראה בשבוע הבא.$k$
FROM (SELECT 1) one LEFT JOIN LATERAL (
  SELECT id, title, unlock_day FROM public.program_content
  WHERE content_type = 'video' AND archived_at IS NULL AND title LIKE $k$שבוע 2:%$k$
  ORDER BY sort_order LIMIT 1) c ON true;
INSERT INTO public.bot_knowledge (source, content_id, title, unlock_day, chunk_index, text)
SELECT 'video', c.id, COALESCE(c.title, $k$סרטון: שבוע 3$k$), COALESCE(c.unlock_day, 15), 0, $k$אוקיי חבר'ה, שבוע מספר 3, ברוכים הבאים. הנה הרגלים שאנחנו כבר עכשיו מתחילים להכניס שוב לחיים שלנו. אז הרגל ראשון זה בעצם לבחור בשמן זית על פני שמן קנולה. למה אנחנו בעצם עושים את זה? כי קודם כל שמן זית זה דבר הרבה יותר טבעי. הוא הרבה יותר טוב לגוף שלנו ויש שם דברים הרבה יותר חשובים שאנחנו רוצים להכניס לגוף שלנו מאשר שמן קנולה שאין בו באמת כלום. דבר שני זה שאנחנו באמת יכולים לשלוט בכמות השמן שנכנסת לנו לצלחת בשמן זית מאשר שמן קנולה. למה אני מתכוון? בסוף כשאנחנו מוזגים שמן הרבה פעמים אנחנו לא שמים לב ושמים המון. ובסוף שתדעו שמן זה משהו עם המון המון קלוריות. כלומר בשמן בכמות קטנה יכולים להיות לכם מאות קלוריות נסתרות שאתם בכלל לא שמים לב אליהן. ובשמן זית שאתם מוזגים מהפייה של שמן זית הרבה יותר קל לשלוט בכמה אתם בעצם שמים. אז קודם כל תשימו לב לכמה שמן אתם באמת מחליצים לצלחת שלכם גם אם זה שמן זית אם זה עכשיו בחביתה אם זה בפסטה אם זה באורז או בכל דבר כזה או אחר שאתם שמים בו שמן וגם תדאגו שזה יהיה משמן זית ככה יהיה לכם הרבה יותר קל לבוא ולשלוט בכמות שאתם שמים כי הפייה היא קטנה. ופה שוב נכנס העניין של הזמינות תדאגו שיהיה לכם שמן זית בבית ותצמצמו את הקנייה של השמן קנולה. אני יודע שמן קנולה זה דבר ומצרך שהוא חשוב בבית וטוב שיהיה אבל אתם שאר בני משפחתכם תשתמשו בשמן זית יותר. ועכשיו הרגל נוסף שמתווסף לנו לחיים זה הורדת הסוכר הנוזלי ביום יום שלנו. איך זה בעצם הולך להיראות? כל פעם שאתם בעצם תיקחו שתייה מתוקה ביום יום שלכם אתם תדאגו לקחת כוס אחת שזה בעצם 200 מיליליטר פלוס אני רוצה שמעכשיו כל פעם שאתם שותים קפה תורידו את כמות הסוכר שלכם בחצי. למה אנחנו בעצם עושים את זה? אז קודם כל סוכר נוזלי לעומת סוכר רגיל מקפיץ הרבה יותר מהר את האינסולין והסוכר בדם מה שגורם בסוף להגירת שומן כמו שאמרתי לכם גם בסרטון הקודם שאינסולין בסוף פוגר שומן וכך אנחנו פחות מצליחים בעצם להוריד בה אחוזי שומן ודבר שני הלחץ דם שלכם בעצם עולה זה אומר הסטרס גם מתחיל לעלות ולכן אנחנו לא רוצים לעשות את זה לאט לאט אנחנו רוצים להפחית כמה שיותר ואתם תראו שגם בסוף אתם תפחיתו כמה שיותר את בעצם צריכת הסוכר הנוזלי שלכם או בכלל הסוכר שלכם ביום יום דבר שני יש המון המון המון קלוריות שמתחבאות לנו בכוס קולה שאתם אוהבים בפנטה שאתם אוהבים או אפילו בקפה שאתם אוהבים אך ורק בגלל הסוכר שנמצא שם ברגע שנוריד אותו אנחנו יכולים להוריד מאות קלוריות ביום יום וכתוצאה מכך אנחנו גם נצליח ולרדת במשקל יותר בצורה קלה ועכשיו להרגל השלישי שמתווסף לנו לחיים וזה בעצם הרגל השינה שלכם אני רוצה שמעכשיו תתחילו לישון טוב איך אנחנו עושים את זה בצורה נכונה ואיך נתאים את זה בעצם לכל אחד אתם עכשיו מסתכלים על הטבלה שנמצאת פה משמאלי ומסתכלים כמה אתם בעצם צריכים לישון איך$k$
FROM (SELECT 1) one LEFT JOIN LATERAL (
  SELECT id, title, unlock_day FROM public.program_content
  WHERE content_type = 'video' AND archived_at IS NULL AND title LIKE $k$שבוע 3:%$k$
  ORDER BY sort_order LIMIT 1) c ON true;
