SELECT 'video', c.id, COALESCE(c.title, $k$סרטון: שבוע 3$k$), COALESCE(c.unlock_day, 15), 1, $k$זה בעצם יעבוד לכל שעת שינה שאתם בעצם ישנים היום אני רוצה שתוסיפו 8 תחשבו כמה זה יוצא ותחלקו ב-2 אתן דוגמה בן אדם שישן עכשיו 6 שעות ביום אני רוצה שאוסיף 8 שזה בעצם יצא 14 יחלק ב-2 וזה יצא לו 7 השעות שאני בעצם רוצה שהוא יישן ביום יום שלו למה אנחנו עושים את זה קודם כל ויסו תיאבון ידוע ממחקרים ששינה לא מספקת גורמת לכם פשוט לאכול יום למחרת הרבה יותר דבר שני זה בניית השריר שלנו והתאוששות הגוף שלכם בסוף למה אנחנו ישנים כדי לתת לגוף שלנו רגע מנוחה לתת לשרירים שלנו רגע להתאושש מהדברים שהם עברו ביום יום כדי להכין את עצמנו ליום החדש והבא ברגע שאתם לא ישנים טוב האימונים שלכם או כל התזונה שלכם ביום יום לא שווה שום דבר כי לא נתתם לגוף שלכם בסוף את המנוחה שהוא צריך כדי לתפקד ביום הבא. עוד משהו חשוב מאוד ששינה עוזרת לנו לעשות זה בסוף להיות אנרגטיים ביום יום יש לנו הרבה יותר פוקוס אנחנו זוכרים דברים הרבה יותר טוב ובסוף אנחנו מצליחים להתקדם בתהליך בצורה הרבה יותר טובה בגלל שיש לנו פשוט כוח לבוא ולעשות את הדברים האלה אם לא ישרנו טוב בלילה אז אף פעם שיהיה לנו את הכוח לבוא ולהמשיך לתפקד ביום יום ולהתמיד בהרגלים שאני נותן לכם איך אנחנו בעצם מגיעים לשינה הכי איכותית שיכולה להיות זה קודם כל לישון בחדר שהוא קר, מזגן, מאוורר, מה שנוח לכם לפתוח חלון אם זה בחורף. דבר שני זה חושך מוחלט תדאגו לסגור את כל החלונות שלכם גם את הפינות החריצים האלה בדלת לנסו לפחות לאטום אותם או לישון במקום שלא תסתכלו עליהם כשאתם קמים בבוקר. דבר שלישי זה בלי אור כחול ומסכים לפני השינה מאוד מאוד יכול לעזור ודבר אחרון לוז שעות שינה מסודר מה זה אומר תקפידו בכל יום לישון באותה שעה תקפידו על 10, 11, 12 מה שנוח לכם אבל לישון באותו זמן כל שעה זה מאוד מאוד יכול לעזור לכם לבוא ולהתרגל לזה גם מבחינת השעון הביולוגי שלכם. ועוד משהו שאני רוצה באמת שיהיה לכם במוח זה שבסוף אני יודע יש פה חבר'ה ששנים כבר שנים 4, 6, 8 שעות אתם צריכים להבין אם אתם רוצים באמת להגלות לפחות את שעות השינה שלכם בשעתיים בשעה אתם צריכים באמת לרצות את זה ואם לא תיכנסו למיטה ותשבו שם ולא תירדמו ותירדמו רק אחרי שעה או שעתיים הכל בסדר העיקר שאתם בסוף עושים את זה ולאט לאט אתם תראו שכבר מהפעם הראשונה שאתם נכנסים למיטה אתם תצליחו להירדם העיקר שבסוף תעבור ותנסו באמת להשתנות עם כוח הרצון שלכם זה בסוף משהו שצריך לקרות וזהו חבר'ה זה השבוע מספר 3 נתראה בשבוע הבא$k$
FROM (SELECT 1) one LEFT JOIN LATERAL (
  SELECT id, title, unlock_day FROM public.program_content
  WHERE content_type = 'video' AND archived_at IS NULL AND title LIKE $k$שבוע 3:%$k$
  ORDER BY sort_order LIMIT 1) c ON true;
