SELECT 'video', c.id, COALESCE(c.title, $k$סרטון: שבוע 4$k$), COALESCE(c.unlock_day, 22), 0, $k$אוקיי חבר'ה, שבוע מספר 4 ברוכים הבאים ועכשיו במקום להוסיף הרגל אנחנו הולכים לשפר לכם הרגל קיים וגם יהיה כמה הרגלים שאנחנו נוסיף במהלך השבוע הזה. אז קודם כל לגבי השיפור שלנו של ההרגל הראשון. אז מעכשיו אני יודע שעד עכשיו עשיתם הליכה פעם בשבוע. מעכשיו אני רוצה שתתחילו ולהעלות את זה לשתי הליכות בשבוע. ממש עכשיו אחרי שאתם מסיימים את הסרטון הזה תלכו ותסמנו באפליקציה איזה שתי ימים הכי נוחים לכם לבוא ולעשות פליכה. ובכן אני רוצה שתתחילו להעלות את מספר הצעדים היומיים שלכם כי בסוף זה מה שמוריד אותנו במשקל מאוד מאוד חשוב תתחילו לעשות את זה וכמו שאמרתי גם בסרטון הקודם אם תצמידו את ההליכה לאיזשהו עוגן שיש לכם ביום יום יהיה לכם הרבה יותר קל לבוא ולהכניס אותה תעשו את זה שלכם לא שלכם העיקר שתעשו את ההליכה מעכשיו ועכשיו עוד הרגל מאוד חשוב שנכנס לנו כבר מהשבוע הזה לחיים שלכם זה להתחיל לאכול בצלחת אחת מה אני בעצם מתכוון? ואני רוצה שמעכשיו, כל פעם שאתם באים לארוחה תתחילו לאכול בצלחת אחת בלי ריפילים או לקחת דברים מהצד נשנושים, כל מיני דברים כאלה למה אנחנו בעצם עושים את הדבר הזה? כי הצלחת אחת עוזרת לשמור לנו על הכמות אבל היא לא מונעת לנו בעצם את הדברים שאנחנו אוהבים לאכול כלומר אנחנו יודעים כמה אנחנו הולכים לאכול באותה ארוחה כי יש לנו בעצם את הצלחת אחת אנחנו שמים לב לכמות ואנחנו גם יכולים להוסיף מה שאנחנו רוצים לאכול אם אנחנו רוצים לאכול צ'יפס אם אנחנו רוצים לאכול המבורגר אם אנחנו רוצים לאכול סלט או אורז או פסטה אנחנו יודעים שאנחנו אוכלים את זה בצלחת אחת והיא שומרת לנו על הכמות בלי בעצם להתחיל לספור קלוריות בלי לקחת כפות מפה כפות משם זה מאוד מאוד קל מאוד מאוד פשוט אין צורך בהתאמצות מיותרת ואין צורך באיזושהי מחשבה מודעת או משהו שאתם עושים עם כוח הרצון שלכם זה פשוט משהו שאתם יכולים להכניס$k$
