INSERT INTO public.bot_knowledge (source, content_id, title, unlock_day, chunk_index, text)
SELECT 'video', c.id, COALESCE(c.title, $k$סרטון: שבוע 5-6$k$), COALESCE(c.unlock_day, 29), 0, $k$אוקיי חבר'ה, ברוכים הבאים לשבוע מספר 5 ו-6 ובשבוע הזה אנחנו הולכים להוסיף הרגלים שהם טיפה יותר קשים לחיים שלכם שהם בסוף יהוו את הבסיס לתהליך שלנו וימשיכו איתכם לטווח הארוך. אז שימו לב, ההרגל הראשון שאנחנו מכניסים לחיים שלנו זה יותר מהרגל זה בעצם סידור הרוחות שלנו. אנחנו מעכשיו הולכים לסדר את הרוחות שלנו בצורה שתהיה הרבה יותר מסודרת כי בסוף סדר הרוחות נכון בונה לנו איזושהי מסגרת ביום יום מסגרת שאנחנו יודעים שאנחנו אוכלים ככה וככה בשעות ככה וככה וזה בסוף מה שבונה לנו את האורח חיים בריא. מה זה בעצם אומר? מעכשיו אתם הולכים לחבר את הארוחת בוקר שלכם והארוחת צהריים שלכם ובעצם נקרא לה ארוחת בואריים זאת הארוחה הראשונה שלכם ביום הארוחה השנייה שלכם ביום זה ארוחת הערב שלכם זה השתי ארוחות גדולות שלכם ביום ששלנו אתם מכניסים את רוב הקלורית שלכם ואוכלים הכי הרבה אז שימו לב זה בעצם שתי ארוחות שמעכשיו הולכות להיות לכם. עוד שתי ארוחות קטנות שהולכות להיות לכם זה ארוחת ביניים וארוחה מתוקה. ארוחת ביניים זאת ארוחה בעצם שאמורה להשביע אתכם לדעת לכם איזשהו שובע במהלך היום בדרך כלל בדרך כלל יש גם כאלה שמוסיפים את זה לפני הבואריים אבל בדרך כלל מוסיפים את זה בין הבואריים לערב שם זה המקום שאנחנו בעצם יותר רעבים יש בעצם הפרש של 6 שעות 7 שעות בין לבין ולכן אנחנו טיפה יותר רעבים במקומות האלה. כל ארוחה שאנחנו הולכים להכניס ביום-יום זה ארוחה קטנה אבל שהיא לא ארוחת ביניים זאת בעצם ארוחה מתוקה שהיא באה בעצם להביא לנו איזשהו סיפוק לחשקים שלנו אם עכשיו אנחנו רוצים מתוק בסוף אמרתי אנחנו לא מונעים את המתוק אז יש לנו את הארוחה הקטנה הזאת ביום-יום שבה אנחנו יכולים להכניס את המתוק שאנחנו רוצים איפה אנחנו מכניסים את הארוחה הזאת לאורך כל היום זה שלכם אני הייתי ממליץ לקבוע איזשהו זמן ביום שבעצם אתם אוכלים את הארוחה המתוקה הזאת אחרי ארוחת ערב לפני ארוחת ערב עדיף לפני ארוחת ערב כדי שבאמת יהיה לכם שינה יותר איכותית אבל אתם יכולים בתכלס להכניס את זה מתי שאתם רוצים. מבחינת כל הכמויות ואיך בעצם הארוחה אמורה להיראות יש לכם את הכל במסמך ממש עכשיו אחרי שאתם מסיימים את הסרטון הזה תלכו לעבור על המסמך יש מסמך שממש מסביר את סידור הארוחות שלכם תעברו עליו מאוד מאוד חשוב שתקפידו שם על הכמויות והדברים זה לא תפריט חבר'ה זה איזשהו מסמך שיסדר לכם כמה אתם בעצם אמורים לאכול בארוחת ביניים ארוחה גדולה לאכול את זה תעברו על זה ואני נותן רגע עיירת צד שגם אותה יהיה כתוב במסמך אם עכשיו יש ימים שאתם יודעים שאתם לא תצליחו לאכול ארוחה אחת גדולה בפעם אחת אין בעיה פשוט תפצו אותה לשתי ארוחות קטנות כלומר לאכול את ארוחת ביניים לפני הצהריים ואחרי הצהריים מתי שאתם בעצם מספיקים ביום יום שלכם בסוף תזכרו שאנחנו עושים את זה כדי ליצור איזשהו לוח זמנים מסודר איזשהו שעון ביולוגי במוח שלנו שיעזור לנו לבוא ולזכור מתי ומה אנחנו אוכלים ביום יום שלנו וזה מאוד מאוד חשוב שתתחילו להקפיד על זה וכמו שאמרתי גם בסרטונים הקודמים אם שכחתם לא הצלחתם ארוחה מסוימת פספסתם פה אכלתם יותר שוקולד פה ושם הכל בסדר העיקר שיום למחרת אתם ממשיכים כרגיל וממשיכים לפי$k$
FROM (SELECT 1) one LEFT JOIN LATERAL (
  SELECT id, title, unlock_day FROM public.program_content
  WHERE content_type = 'video' AND archived_at IS NULL AND title LIKE $k$שבועות 5–6:%$k$
  ORDER BY sort_order LIMIT 1) c ON true;
