SELECT 'video', c.id, COALESCE(c.title, $k$סרטון: שבוע 5-6$k$), COALESCE(c.unlock_day, 29), 1, $k$הסידור ארוחות זה הכל ועוד שתי הרגלים מאוד חשובים שנכנסים לשבוע הזה זה אימון אחד בשבוע ומה שמצטרף אליו זה מנת חלבון בכל ארוחה מה אני מתכוון זה אומר שמעכשיו אתם תקבלו מאיתנו אימון שתצטרכו לבצע אותו ביום אחד בשבוע זה בלי קשר להריחות שאתם עושים קחו את זה בחשבון זה אומר שמעכשיו אחרי הסרטון הזה אתם הולכים ומסמנים באפליקציה איזה יום יהיה לכם הכי נוח לבוא ולעשות אימון כמובן שהאימון יהיה בהתאם לבחירות שלכם שרשמתם לנו לפני אם זה בבית בפארק בחדר כושר כל דבר כזה או אחר שתרצו ואם צריך גם להחליף אין בעיה גם נחליף אבל הכי חשוב שבסוף תבצעו את האימון כי אנחנו רוצים להתחיל לבנות לכם מסת שריר וזה גם מה שהם מתקשר להרגל הנוסף שאנחנו מכניסים לכם חלבון בכל ארוחה בשביל בסוף להצליח לבנות מסת שריר אנחנו צריכים לאכול חלבון ביום יום שלנו זה מה שבונה לנו את המסה למה אנחנו בעצם עושים את זה ברגע שיש לכם מסת שריר יותר גבוהה אתם שורפים יותר קלוריות במנוחה כלומר בן אדם שאין לו מסת שריר גבוהה והוא יושב לידי פה ואני יושב פה אני אשרוף יותר ממנו במנוחה וכתומצאה מכך יהיה לי הרבה יותר קל לבוא ולרד במשקל לגבי החלבון אני רוצה שאתם תכניסו אותו בעיקר בארוחות הגדולות שלכם אוקיי זה יכול להיות שניצל זה יכול להיות עוף זה יכול להיות בשר זה יכול להיות דגים זה יכול להיות טופו לצמחונים מבינינו הכל שפשוט יהיה חלבון בארוחה חלבון מספק וגם בארוחות ביניים שלכם אתם יכולים להכניס את החלבון אפילו עדיף שתכניסו שם את החלבון כי בסוף למה אנחנו מכניסים את החלבון? כי חלבון זה אהב מזון הכי משביע ככל שתאכלו יותר ממנו תהיו יותר שבעים ולכן אנחנו רוצים לשלב אותו בכל ארוחה כדי שגם תצאו ממנה באמת שבעים לטווח הארוך אז גם בארוחות הקטנות ארוחות ביניים אתם יכולים לשלב את החלבון עכשיו לגבי האמון איך אנחנו מכניסים אותו לחיים שלנו בצורה הרבה יותר קלה אז קודם כל תקבעו זמן בלוז שאתם יודעים שהוא הכי נוח לכם ותקבעו אותו כבר בתחילת שבוע תקבעו שביום שלישי ביום רביעי ביום ראשון ביום שני לא משנה איזה יום תבחרו אתם עושים אימון תקבעו אותו שיהיה לכם פה בראש כך יהיה לכם הרבה יותר קל לבוא ולהכין את עצמכם אליו דבר שני זה להכין כבר יום לפני את הבגדים שלכם לאימון תכינו כבר יום לפני או בבוקר שבאותו יום את הבגדים שלכם לאימון אתם צריכים את זה ברגע שיהיה לכם את זה מול העיניים שלכם יהיה לכם הרבה יותר קל לבוא ולעשות את האימון פשוט מאוד ודבר שלישי כמו שאמרתי עם ההליכות תצמידו את האימון להרגל קיים. אם עכשיו אתם יודעים שיש לכם הרגל של הליכות, אז במקום לעשות תהליכה סתם ככה 20-30 דקות, תעשו תהליכה ואליה תצמידו את ההרגל של האימון. כמובן שהייתי מציע לכם להצמיד את זה להרגל אחר, כי ההרגל של ההליכה אני בטוח שהוא עוד לא תמוה בכם ב-100%, אבל אם כן אתם מרגישים שהוא כבר נכנס לכם, וזה לא הרגל שממש קשה להכניס אותו, אז תצמידו את האימון אליו, ואז תוכלו ללכת לחדר כושר, לפארק, כל דבר כזה או אחר, ולאחר מכן בעצם לעשות את האימון שלכם.$k$
FROM (SELECT 1) one LEFT JOIN LATERAL (
  SELECT id, title, unlock_day FROM public.program_content
  WHERE content_type = 'video' AND archived_at IS NULL AND title LIKE $k$שבועות 5–6:%$k$
  ORDER BY sort_order LIMIT 1) c ON true;
INSERT INTO public.bot_knowledge (source, content_id, title, unlock_day, chunk_index, text)
SELECT 'video', c.id, COALESCE(c.title, $k$סרטון: שבוע 5-6$k$), COALESCE(c.unlock_day, 29), 2, $k$ממש להצמיד אותו לאיזשהו הרגל קיים שקיים באורח החיים שלכם, ואז תוכלו בעצם להכניס אותו גם בצורה הרבה יותר קלה. וחשוב לי רגע להגיד, אני יודע שיש פה חבר'ה שלא מתאמנים בכלל ולא התאמנו בחיים שלהם, או לפחות כרגע לא עושים אימונים, וזה בסדר לא לרצות לבוא ולהתאמן, אבל אתם צריכים להבין שאימוני כוח זה משהו שאנחנו צריכים להכניס לחלק מהשגרה שלנו, אם אתם באמת רוצים לבנות אורח חיים בריא. אז כן, לפעמים אתם צריכים לעשות הקרבות, אין מה לעשות. יהיה הקרבות בתהליך הזה אם עכשיו אתם צריכים אולי לא להוציא את הילד מהגן או לוותר על הלימודים שלכם בשביל לעשות אימון. תדאגו תמיד שהאימון יהיה בסדר העדיפויות הראשון שלכם. הוא מבחינתי הכי חשוב ביום-יום שלכם, ואתם צריכים לדאוג לזה כמו שאני דואג לזה וכמו שמיליון אנשים אחרים שחיים אורח חיים בריא דואגים לזה. תדאגו גם אתם ואתם תצליחו להכניס את זה, אז אתם כבר תראו שהאימון לא הופך לאיזושהי מטלה הוא הופך למשהו שאתם עושים באופן טבעי ואפילו בשבילי כבר לאיזושהי הפסקה מהיום. וחבר'ה אני יודע שיש פה כבר אנשים שקיבלו אימון בהתחלה מי שקיבל אימון בהתחלה ראינו לנכון שהוא צריך לקבל כבר את האימון מההתחלה כי אנחנו יודעים שהוא כבר עושה אימונים לפני אם קיבלתם אימון מההתחלה הדבר הזה לא רלוונטי עבורכם אבל אם לא אז כמובן תתחילו ליישם את זה כבר מעכשיו. ועוד משהו שאתם מקבלים כבר השבוע הזה אני יודע יש המון המון תכנים אבל חשוב שתעברו על כולם זה בעצם מדריך רגעים לא צפויים זה בעצם לכל הרגעים שקורים לכם בחיים שאתם לא יכולים לצפות אותם חשוב שגם ברגעים האלו תדעו איך להתנהל בצורה טובה זה יכול להיות יש יום הולדת למישהו בעבודה זה יכול להיות פתאום הילד הקפיץ אותי לשם זה יכול להיות לא יודע פתאום יש לי מבחן יום למחרת בוכן פתע כל דבר כזה או אחר שיכול לגרום לכם לבוא ולנשנש לאכול או לא יודע חתונה או על האש עם חברים כל דבר כזה או אחר תסתכלו על זה תעברו על זה זה לכל הרגעים האלו שאתם לא יכולים לצפות בחיים שלכם וזהו חבר'ה זה בעצם היה השבוע מספר 5 ו-6 תעברו על כל התכנים הם סופר דופר חשובים להמשך התהליך שלנו ותתחילו ליישם וכמו שאמרתי אני רוצה שתתחילו לשים את התזונה והאימונים והסדר יום שלכם בראש סדר העדיפויות לפני כל הדברים האחרים כי ככה בסוף רק מגיעים לתוצאות ברגע שמתעדפים משהו שאנחנו רוצים להכניס לחיים אז יאללה נתראה בשבוע הבא$k$
FROM (SELECT 1) one LEFT JOIN LATERAL (
  SELECT id, title, unlock_day FROM public.program_content
  WHERE content_type = 'video' AND archived_at IS NULL AND title LIKE $k$שבועות 5–6:%$k$
  ORDER BY sort_order LIMIT 1) c ON true;
INSERT INTO public.bot_knowledge (source, content_id, title, unlock_day, chunk_index, text)
SELECT 'video', c.id, COALESCE(c.title, $k$סרטון: שבוע 7-8$k$), COALESCE(c.unlock_day, 43), 0, $k$אוקיי חבר'ה ברוכים הבאים לשבוע מספר 7 ו-8 ובשבוע הזה אנחנו הולכים להכניס משהו לחיים שלכם שמאוד יכול לבוא ולעזור לכם לשרוף הרבה יותר קלורית במהלך היום וכתוצאה מכך גם תוכלו להכניס יותר אוכל. למה אני מתכוון? אני רוצה שמעכשיו תגיעו ל-6,000 צעדים ביום. ולמי שמגיע כבר ל-6,000 צעדים ביום, אגב, אתם יכולים לראות את זה באפליקציה אם לא הסתכלתם עוד שעה, מי שכבר מגיע ל-6,000 צעדים ביום, אז אני רוצה שתעשו 2,000 יותר ממה שאתם עושים. כלומר, אם הייתם עושים 8, אין בעיה, תעשו 10, אוקיי? בסוף אני רוצה להעלות את כמות הצעדים שלכם ביום. עד עכשיו עשינו את זה באמצעות הליכות, העיקר שתגיעו ל-6 אבל אם אתם לא רוצים לעשות את השתי הליכות בשבוע שעד עכשיו עשיתם, אין בעיה, אתם יכולים להיפטר מהם. אבל זה עדיין משהו שאתם עושים ביום-יום שלכם, וזה הרגל שכבר נשאר לכם, אם אתם רוצים להמשיך איתו, בנוסף לאימונים כמובן, אתם מוזמנים בכיף ובאהבה. העיקר שתגיעו ל-6,000 צעדים כל יום בממוצע. כלומר, בסוף שבוע אני רוצה לראות ממוצע 6,000 צעדים פלוס. מי שיגיע ליותר, מדהים. אני אזכיר לכם בקטנה למה אנחנו רוצים ולהמשיך לשפר את ההרגל הזה כי בסוף ככל שאנחנו יורדים במשקל קצב חילוף החומרים שלנו יורד וברגע שאנחנו עושים הליכה אנחנו מעלים את קצב חילוף החומרים ושומרים על מאזן ניטרלי או אפילו עוברים אותו וכתוצאה מכך אנחנו גם שורשים יותר קלורית. אז מאוד חשוב שתתחילו להקפיד על הדבר הזה, צעדים זה משהו קריטי לגמרי בירידה במשקל, אז יאללה. ועכשיו לאיך אנחנו עושים את זה בצורה הכי טובה, הכי קלה, איך אנחנו מעלים זמינות כדי בסוף לבוא ולהכניס את ההרגל לחיים שלנו. אז אנחנו הכנו לכם מדריך במיוחד בשביל זה, במיוחד בשביל להעלות את הצעדים שלכם, לכו ותעברו עליו כבר עכשיו אחרי הסרטון הזה. הוא מאוד מאוד חשוב ומאוד יכול לבוא ולעזור לכם להגיע יותר מ-6,000 צעדים, אפילו להגיע ל-8, 10 ויותר. ועכשיו עוד הרגל שמתווסף לנו לחיים, שזה בעצם שיפור להרגל שכבר הכנסנו לכם, שזה בעצם העלאת צריכת המים שלכם ביום-יום. ועכשיו אני רוצה שתתחילו לצרוך בין 2 ל-3 ליטר באופן קבוע. איך אנחנו בעצם עושים את זה בצורה הכי טובה שיש? אנחנו מסתובבים עם בקבוק מים לידינו. פשוט מאוד, כל מקום שאתם הולכים ביום-יום שלכם, תיקחו את הבקבוק מים איתכם, ככה יהיה לכם הרבה יותר קל לבוא וגם למדוד כמה ליטרים אתם מכניסים ביום. תיקחו בקבוק של חצי ליטר, תמלאו אותו כל פעם, יהיה לכם מאוד קל למדוד את זה, ודבר שני, יהיה לנו מאוד קל לבוא ולשתות במקום עכשיו לרדת לתמי 4 שתי קומות למטה, ארבע משרדים קדימה מי שהבזום יודע ולשתות שם מים. בסוף זה משהו שמאוד יכול לעזור לנו לבוא ולשתות את המים כי הם מאוד מאוד זמינים לנו ומאוד מאוד קלים לנו. אנחנו מסתובבים עם זה בעבודה, עם הילדים, בלימודים וכל דבר כזה או אחר ומאוד קל לנו לבוא ולהכניס את זה אז תתחילו להסתובב עם בקבוק מים ומי שיש לו יותר קל לו לעשות את זה עם תמי 4 שיש לו מאוד זמין או כל מיני דבר כזה או אחר אין בעיה העיקר שתגיעו לבין 2 ל-3 ליטר ביום וזהו בגדול אחרי הסרטון הזה תלכו לעבור על המדריך העלאת צעדים מזכיר לכם וזהו אנחנו נתראה$k$
FROM (SELECT 1) one LEFT JOIN LATERAL (
  SELECT id, title, unlock_day FROM public.program_content
  WHERE content_type = 'video' AND archived_at IS NULL AND title LIKE $k$שבועות 7–8:%$k$
  ORDER BY sort_order LIMIT 1) c ON true;
INSERT INTO public.bot_knowledge (source, content_id, title, unlock_day, chunk_index, text)
SELECT 'video', c.id, COALESCE(c.title, $k$סרטון: שבוע 9-10$k$), COALESCE(c.unlock_day, 57), 0, $k$אוקיי חבר'ה ברוכים הבאים לשבוע מספר 9 ו-10 ובשבוע הזה אנחנו הולכים לשפר משהו שכבר קיים באורח החיים שלכם אם נדאג קצת יותר חודש כבר קיים באורח החיים שלכם והדבר הזה הוא אימונים מעכשיו אם עד עכשיו עשיתם אימון אחד בשבוע אני רוצה שמעכשיו תעשו בין 2 ל-3 אימונים ממש שנעלה קצב באימונים מאוד מאוד חשוב איך אנחנו בעצם נבחר האם צריכים לעשות 2 או 3 יהיה לכם שאלון ממש אחרי הסרטון הזה שהוא בעצם יבחן הייתם צריכים 2 אימונים או 3 אימונים מה שבעצם בהתאם לתהליך ולדברים שאתם עושים היום וגם כמובן בהתאם לאנשים שעשו אימונים כבר מתחילת התהליך. למה אנחנו בעצם מעלים לכם עכשיו עצימות באימונים? כי קודם כל אנחנו רוצים כמו שאמרתי גם בסרטון הקודם לבנות לכם מסת שריר ככל שיש לכם יותר מסת שריר ככה אתם שורפים יותר קלוריד במנוחה וככה אתם מצליחים לרדת במשקל בצורה הרבה יותר קלה. דבר שני זה שאנחנו רוצים בסוף לעצב את הגוף שלכם אימונים זה בסוף מה שמעצב את הגוף מעצב את התחת היפה מעצב את השרירים בידיים מעצב את החזה מעצב את הגף ככל שיש לכם יותר מסת שריר השרירים שלכם יותר בולטים וככה אתם גם כתוצאה מכך נראים הרבה יותר טוב בגוף. ודבר שלישי זה שאימוני כוח בסוף עוזרים לכם לחיות יותר זמן ולהיות בריאים יותר אין מה לעשות אימוני כוח זה משהו שאנחנו רוצים להכניס לאורך החיים שלכם וזה הרגל שלוקח זמן להכניס ולכן אנחנו מכניסים אותו כבר מעכשיו שמעכשיו תתרגלו אליו ותמשיכו איתו לטווח הארוך סופר קריטי תתחילו לעבור על זה וכמו שאמרתי תתחילו להעלות זמינות גם בדברים האלו תתחילו להכניס את זה כעוגן לפני דברים שאתם בעצם כבר עושים ביומיום הרגלים שכבר קיימים לכם ותקבעו לעצמכם שעה ביום כמו שאמרתי בסרטון הקודם מי שרוצה ללכת לעבור עליו איך בעצם מכניסים אימון בצורה קלה לכו תעשו את זה זה בשבוע מספר 5 ו-6 ומעבר לכמות אימונים שאנחנו מעלים לכם אנחנו גם רוצים שתמקסמו את האימונים שלכם כלומר תעשו את האימונים בצורה הכי טובה ולכן הכנו לכם מדריך שממש אחרי הסרטון הזה תלכו לעבור עליו שבעצם יעזור לכם לדעת איך למקסם את האימון בצורה הכי טובה, איך לבנות הכי הרבה מסת שריר, איך להפיק הכי הרבה אנרגיה מהאימון ואיך בעצם לעשות את האימון בצורה הכי טובה וקלה שיכולה להיות. אז לכו תעברו עליו אחרי הסרטון הזה. ושתי הרגלים נוספים שנכנסים לחיים שלנו שאני אחבר אותם ביחד זה הרגל של העדפת זירו על משקאות מתוקים בהעדפת פירות על נשנושים, שוקולדים, כל דבר כזה או אחר. למה אנחנו בעצם עושים את זה? כי בשתייה המתוקה והנשנושים שאתם אוכלים יש המון המון קלוריות לעומת הזירו והפירות שאני רוצה שתתחילו להכניס. וזה, אני מניח שאתם מבינים, מוריד אותנו במשקל. דבר שני לגבי הפירות, הפירות נותנות לנו תחושת צובע הרבה יותר מספקת מאשר שוקולד שאנחנו מכניסים לגוף. כמו שאמרתי, כמו עם הרטבים. השוקולד זה כמו איזשהו קלורית נסתרות שאנחנו מכניסים כי אנחנו לא באמת שבעים מזה. כמו שאמרתי אז עם הרטבים, שוקולד ורטבים זה בתחתית המזון. זה לא גורם לנו להיות שבעים וגם זה מכניס לנו הרבה מאוד קלורית לגוף.$k$
FROM (SELECT 1) one LEFT JOIN LATERAL (
  SELECT id, title, unlock_day FROM public.program_content
  WHERE content_type = 'video' AND archived_at IS NULL AND title LIKE $k$שבועות 9–10:%$k$
  ORDER BY sort_order LIMIT 1) c ON true;
INSERT INTO public.bot_knowledge (source, content_id, title, unlock_day, chunk_index, text)
SELECT 'video', c.id, COALESCE(c.title, $k$סרטון: שבוע 9-10$k$), COALESCE(c.unlock_day, 57), 1, $k$לכן אנחנו תמיד נרצה להעדיף ב-80% מהזמן, לא תמיד, את הפירות וגם כתוצאה מכך גם את הזירו והדברים האלו. ודבר נוסף שאנחנו בסוף רוצים להצליח לעשות פה זה להוריד לכם את החשק למתוק. עד עכשיו עשינו את זה עם זה שהורדנו לכם את הצריכה של בעצם השתייה המתוקה שלכם לכוס אחת במקום כל המשקה או שתי כוסות וגם הורדנו לכם את כמות הקפה. כרגע אנחנו רוצים להוריד לכם גם את הדברים האלו כדי שבסוף נוכל למגר ולהוריד כמה שיותר את צריכת הסוכר שלכם ביום יום שגורמת לנו בסוף לאגור שומן. אז חשוב מאוד שתתחילו להקפיד על זה ב-80% מהזמן שלכם, זה לא צריך להיות ב-100% מהזמן ואסור לכם בעצם לאסור על עצמכם, אני לא מסכים לכם. אתם יכולים לאכול גם שוקולדים ואתם יכולים לאכול גם את השתייה המתוקה ב-20% מהזמן. אבל ב-80% אני רוצה שתתחילו לאכול פירות ומשקאות זירו בלבד. איך אנחנו בעצם עושים את זה בצורה הכי קלה? כמו שאתם כבר יודעים, מעלים ומורידים זמינות, מכירים את זה כבר מהרגלים אחרים שהכנסנו לחיים. במקרה שלנו אנחנו מתחילים להוריד את קניית המתוקים, אם זה השוקולדים, אם זה השתייה המתוקה, אם זה כל הדברים שאתם קונים לבית שלכם, אני יודע חלק מפה יש להם ילדים והם אוהבים מתוקים, אז גם להם זה בריא, תאמינו לי, תתחילו להוריד בכמויות של הדברים האלו מהחיים שלכם. ואותו דבר גם עם העלאת זמינות, אנחנו מורידים דברים שאנחנו רוצים להעיף ומכניסים דברים שאנחנו רוצים להכניס. אנחנו רוצים שכמה שיותר תקנו פירות, יותר משקאות זירו לבית שלכם, אם אתם לא שותים זירו אז מעולה, אבל תקנו יותר פירות וגם תשימו אותם במקום נגלה לעין שלכם, שברגע שאתם פותחים את המקרר, ברגע שיש לכם לא יודע איזושהי סלסלת פירות על השולחן או כל דבר כזה או אחר, תשימו שם את הפירות שיהיה לכם הרבה יותר קל לבוא ולגשת אליהם. ומצד שני, כמו שאנחנו רוצים לראות את הפירות, אנחנו רוצים גם להעלים את המתוקים. כמו שאמרתי, אני לא רוצה שתעלימו לגמרי את המתוקים מהבית שלכם, פשוט תפחיתו את הקנייה שלהם. אז פשוט תשימו אותם במקום שהוא לא נגלה לעין, כמו איזה מגירה גבוהה. ככה גם הילדים שלכם יהיה להם יותר קשה לבוא ולהגיע לזה וגם לכם יהיה הרבה יותר קשה לבוא ולהגיע לדבר הזה. אז פשוט ברגע שתעשו את זה, יהיה לכם הרבה יותר קל גם להעלים את זה מהחיים שלכם. וזהו בגדול. עכשיו עוד דבר שאתם מקבלים השבוע הזה, זה סרטון אדפטציה מטאבולית. זה סרטון בעצם שבא להעשיר את הידע שלכם בכל הדבר הזה שנקרא תהליך ירידה ומשקל. זה סרטון מאוד מאוד חשוב שתראו אותו אם אתם רוצים גם בעתיד לבנות לכם תהליכים לבנות לאחרים תהליכים בסוף אנחנו רוצים לאמן אתכם להיות המאמנים של עצמכם ולדעת איך לחיות אורח חיים בריא בצורה נכונה והסרטון הזה יכול ממש ממש לעזור לכם באיך בעצם בנוי תהליך ירידה ומשקל. מוזמנים ללכת לראות אותו זה בשבילכם אתם לא רוצים החלטה שלכם הפסד שלכם. זה הכל חבר'ה נתראה בשבוע מספר 11 אוהב אתכם.$k$
FROM (SELECT 1) one LEFT JOIN LATERAL (
  SELECT id, title, unlock_day FROM public.program_content
  WHERE content_type = 'video' AND archived_at IS NULL AND title LIKE $k$שבועות 9–10:%$k$
  ORDER BY sort_order LIMIT 1) c ON true;
