SELECT 'video', c.id, COALESCE(c.title, $k$סרטון: שבוע 11-12$k$), COALESCE(c.unlock_day, 71), 0, $k$אוקיי חבר'ה, שבוע מספר 11-12 ברוכים הבאים והשבוע הזה אנחנו הולכים להוסיף עוד כמה הרגלים לחיים שלכם וגם לשפר הרגלים קיימים שכבר יש לכם. אז דבר ראשון שאנחנו מוסיפים לחיים שלכם זה ההרגל של שליש שליש שליש. מה זה בעצם אומר? מעכשיו בצלחת שלכם, שאני יודע שאתם אוכלים עד עכשיו צלחת אחת מעולה, אתם רוצים לחלק את הצלחת שלכם מעכשיו לשליש חלבון, שליש פחמימה ושליש ירק. חלבון וירק כבר יש לכם בצלחת אבל עכשיו אני רוצה שממש תחלקו את הצלחת לשליש שליש שליש. זה יכול להיראות ממש ככה כמו שאני מצביע לכם פה ממש שליש חלבון שליש פחמימה ושליש ירק. מאוד חשוב שתתחילו לעשות את זה, זה הרגל שהוא סופר חשוב כי בסוף הוא מאחד לנו את כל אבות המזון בצלחת אחת בארוחה אחת שאנחנו אוכלים, וזה מה שאנחנו רוצים לדאוג לו כל פעם שיש לנו ארוחה. עוד יתרון שיש לנו בעצם בהרגל השלישים זה שהוא שומר לנו על הכמויות באופן יותר מדויק, בלי שאנחנו בעצם צריכים להקפיד על ספירת קלוריות, כפות ודברים כאלה. איך הוא בעצם עושה את זה? אנחנו יודעים שכל פעם שאנחנו לוקחים צלחת אחת, שזה הרגל שכבר יש לנו מקודם, זה בעצם איזשהו שיפור קטן להרגל הזה. אנחנו יודעים שאנחנו אוכלים לפי קודם כל ירקות, אחר כך חלבון ואז פחמימה, שליש שליש שליש בצלחת, וזה בעצם שומר לנו. שדרוג נוסף שאנחנו מכניסים לחיים שלנו, שזה בעצם שדרוג להרגל הרוטב שעשינו פעם קודמת: עכשיו אני רוצה שבמקום לבחור רוטב אחד פעם בארוחה, אני רוצה שתבחרו רוטב אחד פעם ביום. כלומר בארוחה מסוימת שאתם אוכלים ביומיום שלכם תיקחו רוטב אחד, אם זה קטשופ, מיונז, חרדל, כל דבר כזה או אחר שאתם אוהבים. גם טחינה נחשבת כרוטב. למה אנחנו בעצם עושים את זה? אני אזכיר לכם, כי בסוף ברטבים האלו יש המון המון קלוריות נסתרות והם גם לא משביעים אותנו.$k$
FROM (SELECT 1) one LEFT JOIN LATERAL (
  SELECT id, title, unlock_day FROM public.program_content
  WHERE content_type = 'video' AND archived_at IS NULL AND title LIKE $k$שבועות 11–12:%$k$
  ORDER BY sort_order LIMIT 1) c ON true;
