SELECT 'video', c.id, COALESCE(c.title, $k$סרטון: שבוע 11-12$k$), COALESCE(c.unlock_day, 71), 1, $k$ככל שנפחית אותם כמה שיותר, כך יהיה לנו הרבה יותר קל להצליח בתהליך. וההרגל הכי חשוב בכל השבוע הזה שאני רוצה שתתחילו להכניס לחיים שלכם, זה התחלת הדילול של המאכלים הלא בריאים בחיים שלכם והכנסת הטובים ב-80% מהזמן. למה אני מתכוון? יהיה לכם מדריך במיוחד בשביל זה על תזונה בריאה, שאני רוצה שתעברו עליו ותתחילו ליישם לפיו מה אתם בעצם מכניסים לפה שלכם ביום יום. ודבר נוסף שתקבלו זה רשימת קניות שהכנו לכם, רשימת קניות מסודרת שתביא לכם תחליפים ודברים שאולי אתם לא מכירים, או חלקכם כבר מכירים וקונים, להמון המון דברים שהם לא בריאים או כן בריאים. והדברים שכתובים שם זה תכלס דברים שאתם חייבים שיהיו לכם בבית. וכמו שעשינו אז עם הנשנושים והשתייה המתוקה וכל הדברים האלו, שהורדנו בעצם את הזמינות שלהם או שמנו אותם במקום גבוה שיותר קשה לנו לבוא ולהגיע אליהם, ככה אני רוצה שתעשו גם עם הדברים האלו שאתם אוכלים ביומיום שהם פחות בריאים, שהם לא כתובים ברשימה: תורידו את הזמינות שלהם, ובמקום זה תעלו ותקנו את הדברים שכתובים ברשימה. בסוף כל הדברים האלו שכתובים לכם ברשימת הקניות זה מאכלים בריאים שאתם רוצים לתת לגוף שלכם. מאכלים בריאים בדרך כלל הם מאכלים שמאוד מאוד משביעים אותנו, ומנגד גם יש בהם הרבה פחות קלוריות ממאכלים אחרים. אז אחרי הסרטון הזה אני רוצה שתעברו על הרשימה הזאת ותתחילו ליישם. ואני יודע, זה קשה לעשות שינוי ככה בחיים שלכם, אין מה לעשות, אבל בסוף כדי להתרגל לאורח חיים חדש צריך לבוא ולעשות את השינוי הזה. ולכן התהליך הזה נוצר, כדי לעשות אותו בצורה הכי קלה והכי פשוטה והכי טובה לכם, כדי בסוף להצליח. אז יאללה, תעשו את זה, תעברו גם על המדריך תזונה בריאה וגם על רשימת הקניות. נתראה בשבוע הבא.$k$
FROM (SELECT 1) one LEFT JOIN LATERAL (
  SELECT id, title, unlock_day FROM public.program_content
  WHERE content_type = 'video' AND archived_at IS NULL AND title LIKE $k$שבועות 11–12:%$k$
  ORDER BY sort_order LIMIT 1) c ON true;
