SELECT 'video', c.id, COALESCE(c.title, $k$סרטון: שבוע 13-15$k$), COALESCE(c.unlock_day, 85), 0, $k$אוקיי חבר'ה, ברוכים הבאים לשבועות 13 עד 15 ובשבועות האלו אנחנו הולכים להעלות עוד טיפה את מספר הצעדים שלכם. מה זה אומר, תכל'ס? אני רוצה שמעכשיו, אם עד היום עשיתם 6,000 צעדים ומי שהקפיד על זה מעולה, מי שלא, להתחיל לעשות זה מאוד מאוד מאוד חשוב להמשך התהליך, ואם לא ראיתם תוצאה זה כנראה, ככל הנראה, בגלל זה, לא רק, אבל ככל הנראה. מה שאני רוצה שתעשו אז שתעלו בעצם את מספר הצעדים שלכם מ-6,000 ל-8,000 כלומר פלוס 2,000 ומי שכבר עושה 8,000 או יותר אז להעלות בעוד 2,000 נוספים. כלומר אם עשית 10, תעשה 12. בסוף אנחנו רוצים להעלות את מספר הצעדים כדי להתחיל לשרוף יותר קלורט וכדי בסוף להעלות את חילוף החומרים, מה שיגרום לנו גם לשרוף יותר קלורט. ולמי שלא יודע איך להכניס את הצעדים לחיים שלו בצורה הרבה יותר קלה, אז קודם כל יש את ההליכות שדיברנו עליהן כבר אז בשבועות הראשונים, תזכרו אותן, אם אתם צריכים תתחילו לעשות גם הליכות, ויש גם את המדריך שהכנו לכם הוא נמצא בשבוע 7-8 לכו תעברו עליו תראו אותו יהיה לכם הרבה יותר קל לבוא ולהתמיד בדבר הזה אם תעבדו לפי המדריך. דבר שני שאנחנו מצרפים לשבוע הזה ואני יודע שלחלקכם אולי זה יהיה טיפה קשה אבל אנחנו צריכים לעשות את זה כדי בסוף להצליח בתהליך וליצור לעצמכם איזשהו אורח חיים שהוא יותר טוב אז הדבר הזה זה להוריד את הסוכר והקפה שלכם לגמרי כן אני יודע שיש פה חבר'ה שנפל עליהם עכשיו איזשהו משאית אבל הכל בסדר אנחנו רוצים לעשות את זה בסוף כדי להוריד את רמות הסוכר שלכם בדם וכדי להוריד את צריכת הקלוריות היומית שלכם ביום יום. מי שרוצה לשמוע עוד את היתרונות על הדבר הזה יכול לחזור כבר לשבועות הקודמים איפה שדיברתי על הורדת הקפה ושם לראות את היתרונות בעצם של הורדת הסוכר בקפה שלכם. וזהו בגדול לשבוע הזה אני יודע לחלקכם זה יהיה אולי טיפה יותר קשה לבוא ולעשות את הדברים האלו אבל בסוף זה הדברים שמביאים אותנו לתוצאה וכן אולי חלקכם גם מצליחים לעשות הליכה כל יום וזה בסדר הכל בסדר אם לעשות הליכה כל יום אני עושה הליכה כמעט כל יום ואין שום פסול בזה הכל טוב אגב אתם צריכים להגיע לשמונת אלפים צעדים בממוצע אז זה הכל אנחנו נתראה בשבוע מספר 16 יאללה ביי$k$
FROM (SELECT 1) one LEFT JOIN LATERAL (
