SELECT 'video', c.id, COALESCE(c.title, $k$סרטון: שבוע 25-28$k$), COALESCE(c.unlock_day, 169), 1, $k$קורה לי עכשיו בחיים אני היום עושה אימון החלטתי שאני עושה אימון ביום הזה והזה אני עושה אימון ביום הזה וזה ואני אדחה דברים בשביל לעשות את האימון הזה כי בסוף זה הבריאות שלכם חבר'ה אנחנו לא מדברים פה סתם על רק לבוא ולעצב את הגוף זה אשכרה הבריאות שלכם זה מה שיחזיק אתכם יותר שנים קדימה זה מה שיחזיק אתכם אנשים יותר אנרגטיים יותר בריאים יותר כיפים יותר צעירים זה בסוף מאוד מאוד חשוב ואם זה חשוב לכם כמו שזה חשוב לי אני מאמין שאתם יכולים לדחות את הדבר הזה שכל כך לא כזה חשוב לכם בשביל לעשות אימון בשביל להקפיד בארוחה שלכם בשביל לישון יותר טוב תעשו את הדברים האלו זה מאוד מאוד חשוב כדי להצליח בתהליך אתם צריכים להבין את זה בסוף זה צריך לבוא עמכם ואם תעדפו את הדברים האלו בסדר עדיפויות יותר גבוה אתם תצליחו לבוא ולהתמיד בהם אם אני אתן לכם רגע דוגמה על עצמי שאני מסדר את סדר היום שלי את הלו"ז שלי לשבוע אני קודם כל דבר ראשון מכניס את הארוחות שלי את האימונים שלי ואז רק אז את כל שאר הדברים בהתאם לאור החיים שלי אני מתאים את הדברים שיש לי לעשות את העבודה שלי את העיסוקים שלי את כל הדברים שאני עושה ביום יום לאור החיים שלי אם אני יודע שהמטרה שלי היא ככה וככה וככה באימונים אני קודם כל מכניס את האימונים אני קודם כל מכניס איפה אני אוכל כמה זמן יש לי הפסקה כמה זמן דברים כאלו וככה אני בונה את סדר היום שלי אני קודם כל מתחיל עם הדברים שמאוד חשובים לי שזה בסוף הבריאות שלי ואז אני ממשיך לדברים האחרים שגם חשובים לי מאוד שלא תטעו אני מאוד אוהב את העבודה שלי אבל הם חשובים לי פחות או יותר מהבריאות שלי אני מתעדף תמיד הבריאות שלי בסדר עדיפויות הראשון תמיד מתחיל עם הדברים שחשובים לי אחר כך עובר לדברים שפחות חשובים לי במילים יותר פשוטות זה פשוט מתעדף את אורח החיים שלכם אתם לא הולכים לפי מה שקורה בחוץ לפי הדברים שקופצים לכם ביומיום אתם קודם כל מתעדפים את אורח החיים שלכם ואת הדברים שעושים אתכם יותר בריאים ואז רק מכניסים את כל הדברים בחוץ תיתנו לעצמכם לשלוט באורח החיים שלכם וככה יהיה לכם הרבה יותר קל לבוא ולהגיע לתוצאה שאתם רוצים וזהו בגדול נתראה בסרטון הבא$k$
