SELECT 'video', c.id, COALESCE(c.title, $k$סרטון: שבוע 29-32$k$), COALESCE(c.unlock_day, 197), 0, $k$ברוכים הבאים לשבועות 29 עד 32 ובשבועות האלה אתם הולכים אשכרה ללמוד איך בעצם לאמן את עצמכם, איך באמת לבנות אימונים לעצמכם, איך להיות המאמן של עצמכם ובמיוחד בשביל זה הכנו לכם מסמך שיעזור לכם לבנות תוכנית אימונים לעצמכם אם זה למאסה, אם זה לכיתוב, אם זה ל-recomposition כל התהליכים האלו יהיו כתובים שם בצורה ברורה כדי שבסוף תבינו ותדעו איך לעשות את זה גם בהמשך, אחרי שאתם עוזבים את התוכנית שלנו או כל דבר כזה או אחר. עוד כמה דברים שיהיו במסמך זה Progressive Overload או איך להתאים באמת את האמון למצב הנוכחי שלכם, בית, פארק חדר כושר, להתאים אותו לזמן שלכם. אני יודע אולי לא תיישמו את הדברים שכתובים שם כבר עכשיו אבל שיהיה לכם בראש לכו תקראו את זה, תעברו עליו ובהמשך אם תרצו גם לבנות אימון לעצמכם אז באהבה ובכיף יש לכם את המסמך הזה. זה בגדול, זה היה השבוע הזה, נתראה שבוע הבא.$k$
FROM (SELECT 1) one LEFT JOIN LATERAL (
  SELECT id, title, unlock_day FROM public.program_content
  WHERE content_type = 'video' AND archived_at IS NULL AND title LIKE $k$שבועות 29–32:%$k$
  ORDER BY sort_order LIMIT 1) c ON true;
INSERT INTO public.bot_knowledge (source, content_id, title, unlock_day, chunk_index, text)
SELECT 'video', c.id, COALESCE(c.title, $k$סרטון: שבוע 33-36$k$), COALESCE(c.unlock_day, 225), 0, $k$אוקיי חבר'ה, ברוכים הבאים לשבוע 33-36 ובשבוע הזה אנחנו הולכים להכניס לכם עוד שיפור להרגל שיש לכם כבר היום שזה באמת שיפור שמאוד מאוד יכול לבוא לעזור לכם בהמשך החיים שלכם ובאורך החיים שלכם. אני אתחיל ולהגיד לפני שאני אומר את השיפור זה שאנחנו כבני אדם לא נועדנו לאכול כל כך הרבה במהלך היום. אתם לא שמים לב לזה אבל היום יש המון המון המון אוכל זמין. תמיד המקרר מלא תמיד יש אוכל על השולחן פירות נשנושים ותכלס זה טוב ככל שיש יותר שפע יותר כיף אתם אוכלים יותר בטעם אבל אנחנו רוצים גם לשמור על איזשהו כמות מסוימת שאנחנו אוכלים ביומיום שלנו שהיא גם מספקת אותנו אבל בלי לאכול כל היום אני לא רוצה שתאכלו כל היום ולכן אנחנו מכניסים פה עכשיו הרגל שנקרא שתי ארוחות ביום כלומר אם עד היום אכלתם ארבע שהן שתיים גדולות ושתיים קטנות היום אני רוצה שתאכלו רק שתיים גדולות ובמידה ואתם רוצים עוד משהו קטן או שיש איזשהו ימים שאתם רוצים לאכול עוד משהו או שמתחשק לכם ואתם רעבים אז אתם יכולים להכניס כלומר עוד ארוחה קטנה במהלך היום. כן אני רוצה שתגיעו לכמות חלבון שאתם צריכים כמו שאמרנו בין 1.6 ל-2.2 תמיד לשאוף ל-2 זה בעצם השאיפה שאנחנו רוצים שתגיעו אליה אבל חשוב שאם אתם לא מצליחים להגיע בשתי ארוחות הגדולות האלה לכמות החלבון הזאת אז אין בעיה תיקחו הארוחה הקטנה הזאת ותוסיפו גם שם את כמות החלבון שאתם צריכים. כן חשוב לי להגיד שהארוחות האלה יהיו טיפה יותר גדולות ממה שאתם אוכלים היום ביום יום אבל זה יסדר לכם את הארוחה בפעם אחת גם יחסוך לכם זמן בארוחות גם יעשה אתכם שבעים להרבה יותר זמן וגם זה הרבה יותר בריא לתת למערכת העיכול לעבוד פעמיים ביום מאשר ארבע פעמים ביום. יהיה לכם פשוט הרבה הרבה יותר טוב. ואני גם מניח שאתם כבר עכשיו הרבה פחות רעבים בין הארוחות ויהיה לכם הרבה יותר קל לבוא ולהכניס את הרגל הזה לחיים שלכם. עוד משהו שמאוד יכול לעזור לכם זה בעצם לשתות יותר מים ביום יום אם עד עכשיו שתיתם בין 2 ל-3 תתחילו לשתות בין 2.5 ל-3.5 ליטר זה ייתן לכם איזושהי תחושת צובע בגוף הבטן שלכם תהיה טיפה יותר מלאה ואתם באמת תתחילו לראות ששתי ארוחות ממש מספיקות לכם ביום יום. אז זה בגדול חבר'ה זה היה השבוע הזה נתראה בשבוע הבא.$k$
FROM (SELECT 1) one LEFT JOIN LATERAL (
  SELECT id, title, unlock_day FROM public.program_content
  WHERE content_type = 'video' AND archived_at IS NULL AND title LIKE $k$שבועות 33–36:%$k$
  ORDER BY sort_order LIMIT 1) c ON true;
INSERT INTO public.bot_knowledge (source, content_id, title, unlock_day, chunk_index, text)
SELECT 'video', c.id, COALESCE(c.title, $k$סרטון: חלק 2$k$), COALESCE(c.unlock_day, 29), 0, $k$אוקיי חבר'ה, ברוכים הבאים לחלק מספר 2 בתהליך שלכם. אז כן, אני יאיר, מכירים אותי כבר בסרטונים הקודמים, והיום אנחנו הולכים לעבור לחלק השני בתהליך. מעכשיו, כל שבועיים יתווסף אליכם הרגל או שיפור להרגל החדש שיש לכם בחיים. שימו לב, בחלק הזה אנחנו לא רק מוסיפים, יהיה גם דברים שאנחנו נוסיף, אבל אנחנו יותר משפרים הרגלים קיימים ובונים לכם באמת את האור החיים ואת הסדר ביום. אז השבוע הזה בעצם מתווסף אליכם מדריך חדש שמעכשיו אתם הולכים לעבוד לפיו. את ההרגלים אתם תראו כבר בסרטון הבא, בשבוע מספר 5 ו-6, אבל עכשיו אני רוצה להסביר לכם את המדריך המאוד חשוב שמעכשיו אתם הולכים לעבוד לפיו. אז המדריך הזה נקרא ארוחות שישי, מסעדות ואירועים מיוחדים. מה זה בעצם אומר? אנחנו חיים במדינת ישראל. מניח שכולכם יודעים את זה, מניח שרובכם לפחות חיים במדינת ישראל. אז אתם יודעים שבמדינת ישראל יש הרבה חגים, יש הרבה פעמים שאנחנו יוצאים למסעדה, יש הרבה פעמים אירועים מיוחדים שאנחנו לא מוכנים אליהם, וגם מהיותנו ישראלים יש גם ארוחות שישי, שבארוחות שישי אנחנו מתפנקים. אז אני רוצה שאתם תדעו איך בעצם להתנהל במצבים האלו בצורה הכי טובה ולמקסם גם את התוצאות בימים האלו שאנחנו צורכים הרבה יותר קלוריות ביום-יום. איך אנחנו בעצם עושים את זה? אתם תעברו על המדריך שם יהיה לכם בצורה מפורטת ותקראו אותו כמה וכמה פעמים, כי כל שישי אתם בסוף תצטרכו אותו למי שעושה פה קידושים, אז תעברו עליו ולאט לאט אתם כבר תראו שאתם זוכרים אותו באופן אוטומטי וזה הכל בגדול. אנחנו נתראה בשבוע מספר 5 ו-6, יאללה לכולם.$k$
FROM (SELECT 1) one LEFT JOIN LATERAL (
  SELECT id, title, unlock_day FROM public.program_content
  WHERE content_type = 'video' AND archived_at IS NULL AND title LIKE $k$חלק 2:%$k$
  ORDER BY sort_order LIMIT 1) c ON true;
INSERT INTO public.bot_knowledge (source, content_id, title, unlock_day, chunk_index, text)
SELECT 'video', c.id, COALESCE(c.title, $k$סרטון: חלק 3$k$), COALESCE(c.unlock_day, 85), 0, $k$ברוכים הבאים לחלק מספר 3 ובחלק הזה אתם הולכים לדייק, לשפר, לנתח בצורה הרבה יותר טובה את ההרגלים הקיימים שיש לכם היום ובסוף להביא את עצמכם למצב של אורח חיים בריא. כן חשוב לי להגיד שאם הגעתם עד לפה ולא ראיתם עד עכשיו תוצאה, אז זה הזמן להתחיל להקפיד על הדברים, להיות על הדברים, באמת להשקיע, באמת להקריב כי בסוף אם לא תקריבו ואם לא תשקיעו, אם לא תביאו את עצמכם למצב שאתם באמת רוצים לבוא ולהתמיד בדבר הזה זה פשוט לא יעבוד. אז חבר'ה זה הזמן אם אתם לא רואים תוצאה ואם אתם רואים אז אתם מדהימים ומעולים ותמשיכו ככה אנחנו עכשיו רק משפרים ומדייקים. אז מה אתם הולכים לעבור בשלב הזה כמו שאמרתי? שיפורים ודיוקים בעצם להרגלים הקיימים שלכם אם יש לכם היום הרגל של תזונה אנחנו נשפר אותו קצת יותר הרגל של אימונים אנחנו נתחזק אותו ונשפר אותו יותר כל הדברים האלו לוז הארוחות אנחנו נדאג בעצם שאורח החיים באמת נטמע בכם שזה בדיוק מה שבאנו לעשות בחלק הזה. ומעבר לזה חשוב לי שעכשיו תדעו שבחלק שלוש יהיה לכם סרטון והרגלים או שיפורים חדשים כל שלושה שבועות. כמו שבחלק שתיים היה כל שבועיים אז בחלק שלוש יהיה לכם כל שלושה שבועות. אז שימו לב לזה מאוד חשוב שתראו את הסרטונים האלה ומאוד חשוב שתשימו לב לתגישים שאנחנו נותנים וזה הכל נתראה בסרטון הבא תעברו אליו עכשיו.$k$
FROM (SELECT 1) one LEFT JOIN LATERAL (
  SELECT id, title, unlock_day FROM public.program_content
  WHERE content_type = 'video' AND archived_at IS NULL AND title LIKE $k$חלק 3:%$k$
  ORDER BY sort_order LIMIT 1) c ON true;
INSERT INTO public.bot_knowledge (source, content_id, title, unlock_day, chunk_index, text)
