SELECT 'video', c.id, COALESCE(c.title, $k$סרטון: צימוד הרגלים$k$), COALESCE(c.unlock_day, 1), 0, $k$אוקיי, אז בסרטון הזה אני הולך להסביר לכם על שיטה שאנחנו בעצם משתמשים בה בתהליך על מנת להשתמש בהרגלים הקיימים שלנו, כדי להכניס הרגלים טובים לחיים שלנו. בדרך כלל זה יהיה הרגלים הרעים שלנו. ולשיטה הזאת קוראים צימוד הרגלים. למה בעצם קוראים לה צימוד הרגלים? כי אנחנו מצמידים הרגלים אחד לשני, ממש מצמידים הרגל שכבר קיים לנו באורח החיים, להרגל שאנחנו רוצים להכניס לאורח החיים שלנו, ואז אנחנו נפתרים מההרגל שכבר קיים לנו, בדרך כלל זה יהיה הרגל רע. בעצם איך השיטה הזאת עובדת? אתן לכם את הדוגמה הכי פשוטה שאפשר להבין מהדבר הזה. שתי כוסות מים לפני הארוחה. מי שכבר יודע, אנחנו בשבוע הזה, בשבוע הראשון, מוסיפים שתי כוסות מים לפני הארוחה. אם עוד לא ראיתם סרטון, אחר כך אתם כבר תראו אותו, נעשה לכם טיפה ספוילר. אבל בגדול, שתי כוסות מים לפני הארוחה נותנים לנו שובע מוקדם לפני הארוחה. ממש, אנחנו מגיעים לארוחה כשהבטן שלנו טיפה יותר מלאה, ואנחנו אוכלים בעצם את הארוחה וכתוצאה מכך הדבר הזה יכול למנוע הרגל רע שיש לנו כבר בחיים, בולמוסים, אכילה מופרזת, כל מיני דברים כאלו שבאים אחרי הארוחה. ברגע שאנחנו בעצם הצמדנו איזה שתי כוסות מים לפני הארוחה, שהארוחה היא בעצם איזשהו עוגן שיש לנו בחיים, כלומר כל פעם, כל יום אתם בעצם תאכלו ארוחה, אנחנו בעצם עזרנו לעצמנו לבוא ולזכור את ההרגל הזה. לא הפעלנו איזושהי מחשבה מודעת, אנחנו פשוט יודעים שלפני הארוחה אנחנו תמיד עושים את ההרגל הזה. זה משהו שמאוד יכול לעזור לנו לבוא ולהכניס אותו לחיים שלנו בצורה הרבה יותר קלה, וכתוצאה מכך הרגל הזה גם ימנע לנו את ההרגל הרע שהוא אכילה מופרזת, בולמוסים, דברים כאלו. לאט לאט ברגע שאנחנו נתרגל לזה ונעבוד על זה, אנחנו נראה שבאופן אוטומטי, לפני הארוחה אנחנו כבר נלך לקחת שתי כוסות מים. בלי מחשבה מודעת, בלי צורך באיזשהו כוח רצון מטורף. פשוט נלך וניקח שתי כוסות מים ולאחר מכן כשזה קורה באופן אוטומטי אתם תראו שלאט לאט ההרגל הרע מתנדף או עף מהחיים שלכם כמו שהכנסתם את הטוב ככה אתם מוציאים את הרע לאט לאט לא בבת אחת בהדרגתיות. עוד דוגמאות לצימוד הרגלים זה יכול להיות ללכת אחרי שאתם חוזרים מהעבודה. כלומר, אתם יודעים שאתם חוזרים מהעבודה, זה איזשהו בלוק ביום שלכם, איזשהו עוגן ביום שלכם, אתם מצמידים לו את ההרגל הטוב שאתם רוצים להכניס, אם זה ההליכה שאתם רוצים להכניס ביום יום שלכם, אתם מצמידים את זה פה, ואתם יודעים שישר אחרי העבודה אתם ישר הולכים. תחשבו על זה לדוגמה שכמו שאתם הולכים לצחצח שיניים בבוקר, אחרי זה אתם מתקלחים, אחרי זה אתם שמים בגדים כל הדברים האלו בסוף הרגלים שאתם עושים ביום יום שלכם. אותו דבר עם ההליכה, אותו דבר עם המים. אתם עושים את זה פעולה אחר פעולה. פשוט מצמידים עוד הרגל חדש שאתם רוצים להכניס. אז זה בגדול, חשוב מאוד שתזכרו את השיטה הזאת, היא הולכת ללוות אותנו לאורך כל התהליך, אז אני רוצה שתתמקצעו בה, ואגב, אתם יכולים להכניס אותה לעוד הרבה מאוד תחומים בחיים שלכם. וזהו, נתראה בשבוע הבא.$k$
FROM (SELECT 1) one LEFT JOIN LATERAL (
  SELECT id, title, unlock_day FROM public.program_content
  WHERE content_type = 'video' AND archived_at IS NULL AND title LIKE $k$%צימוד הרגלים%$k$
  ORDER BY sort_order LIMIT 1) c ON true;
