SELECT 'video', c.id, COALESCE(c.title, $k$סרטון: אדפטציה מטבולית$k$), COALESCE(c.unlock_day, 57), 0, $k$אוקיי, אז בסרטון של היום אני הולך להשאיר לכם טיפה יותר את הידע בתהליך למשהו שנקרא אדפטציה מטאבולית. שזה בעצם איזשהו משהו שקורה לכם בתהליך ירידה במשקל, שכתוצאה מכך אתם נתקעים במשקל שיש לכם. היום בסרטון אני אסביר לכם מה זה בעצם אומר ואיך אתם בעצם מתמודדים עם הדבר הזה. אז קודם כל אדפטציה מטאבולית זה בעצם מצב שהגוף שלכם נתקע, שקצב חילוף החומרים שלו יורד ממש לתחתית לאפס, והוא בעצם לא מצליח יותר לשרוף קלוריות במהלך היום. למה זה קורה? כי הגוף שלנו הוא גוף חכם והוא תמיד מכוון לכמה שיותר מצב ניטרלי בגוף למצב מאוזן כלומר ברגע שאתם בתהליך ירידה במשקל ואתם רוצים לחתוך בקלוריות שאתם אוכלים ביום-יום הכנסתם את הגוף שלכם לאיזשהו מלחמה לאיזשהו מגננה קטנה עם עצמו והוא רוצה תמיד לבוא ולהתאזן לשים את הקו בעצם באמצע שהוא מוציא כמו שהוא מכניס. ולכן באיזשהו שלב אתם תגיעו למצב זה יכול לקרות לכם יש כאלה שזה לא קורה להם כי הם שומרים על קצב חילוף החומרים שלהם בהליכות בהורדת סוכר בכל מיני דברים כאלו אבל זה יכול לקרות וברגע שזה קורה המשקל שלכם ייתקע אתם תרגישו ששבוע שבועיים שלוש אתם לא מצליחים לרדת וזה בסדר גמור זה משהו שיכול לקרות בתהליך מה אנחנו בעצם עושים במצב הזה אז ברגע שזה קורה יש לנו שתי אפשרויות קודם כל אפשרות ראשונה שאנחנו תמיד הולכים אליה זה המסת פחמימות אנחנו רוצים בעצם להעמיס טיפה יותר פחמימות ממה שאכלנו ביום-יום עד עכשיו כדי ליצור איזשהו גירוי בחילוף החומרים ובעצם לעבוד על הגוף שהתחלנו עכשיו להעלות טיפה במשקל ברגע שתעשו את זה הגוף התחיל להבין שאתם עולים טבע משקל אז הוא יחזור למצב שהוא פחות ניטרלי ויעשה לאזן למעלה ואז מה שאתם תעשו זה ישר תחתכו את הפחמימות ואז תמשיכו כרגיל עושים את ההעמסה הזאת לשלוש ארבע ימים לא יותר מזה ואז רואים איך הגוף משתפר במידה וזה לא עובד יש לנו עוד דבר שנקרא reverse diet שזה האופציה השנייה שבמצב הזה אנחנו בעצם רוצים להעלות את צריכת$k$
