  ORDER BY sort_order LIMIT 1) c ON true;
INSERT INTO public.bot_knowledge (source, content_id, title, unlock_day, chunk_index, text)
SELECT 'video', c.id, COALESCE(c.title, $k$סרטון: אדפטציה מטבולית$k$), COALESCE(c.unlock_day, 57), 1, $k$הקלורית שלנו להוסיף אפילו עוד ארוחה קטנה ביומיום ובעצם לעבוד על הגוף שלנו שאנחנו עכשיו הולכים קדימה וחוזרים אחורה בעצם למצב הקודם עושים איזושהי מסה קטנה לתקופה מאוד קצרה שיכול להיות בין שבוע וחצי לשבועיים וחצי משהו כזה ואחר כך אנחנו בעצם חותכים את הקלורית האלה וממשיכים בתהליך שלנו כרגיל למטה ככה, במידה ואתם נתקעים שוב, אתם עושים את זה פשוט שוב וממשיכים קדימה. קודם כל העמסת פחמורות, אחר כך רווירס דיאט. עכשיו את כל ההסברים איך אנחנו בעצם עושים את זה בצורה הכי טובה, ואיך אנחנו משלבים עוד קלוריות ביום יום, אנחנו נכין לכם במסמך מסודר שיהיה לכם ממש אחרי הסרטון הזה, שתוכלו ללכת אליו, ושם אתם בעצם תוכלו לראות הסבר מלא על מה שאמרתי פה, וגם הסבר מלא על איך אתם משלבים את זה בחיים שלכם. כן משהו מאוד חשוב שאתם צריכים להבין, זה שלא כל פעם שאתם נתקעים במשקל זה בהכרח אדפטציה מטאבולית אם עכשיו אתם בשלבים יחסית מוקדמים של התהליך ואתם מקפידים על ההרגלים אבל אתם לא מגיעים לגירעון קלורי אז ברור שאתם לא תרדו במשקל, קחו את זה בחשבון. וגם אם אתם עכשיו בשלב מאוחר יותר בתהליך ואתם נתקעים במשקל לא בטוח שזה אדפטציה מטבולית יכול להיות שפשוט אתם יורדים באחוזי שומן ועולים במסת שריר ולכן המשקל נשאר באותו מקום. אז איך באמת תדעו שאתם מורידים אחוזי שומן ומעלים בשריר פשוט תסתכלו על הגוף שלכם תמדדו את ההיקפים שלכם שוב כמו שמדעתם כבר בהתחלה ושימו לב אם השריר שלכם עולה ואם גם אחוזי שומן שלכם בבטן יורדים. הכי פשוט זה ללכת למראה, להסתכל עליה. אם אתם רואים שהבטן ירדה בשבועיים האחרונים אבל עדיין אתם באותו משקל, אז אתם יודעים שהכל טוב ואתם בדרך נכונה. וזהו בגדול, עכשיו לכו תעברו על המדריך של הדלתציה המטבולית שיסביר לכם בצורה הרבה יותר טובה איך להתנהל במצבים האלה. חשוב שתדעו איך להתנהל, זה מאוד מאוד יכול לעזור לכם גם להמשך החיים וגם בתהליך שלנו. אז זהו בגדול, נתראה בסרטון הבא.$k$
FROM (SELECT 1) one LEFT JOIN LATERAL (
  SELECT id, title, unlock_day FROM public.program_content
  WHERE content_type = 'video' AND archived_at IS NULL AND title LIKE $k$%אדפטציה מטבולית%$k$
  ORDER BY sort_order LIMIT 1) c ON true;
COMMIT;

-- Check: chunks per video, and any not tied to a video (should be none). Return this.
SELECT title, count(*) AS chunks, min(unlock_day) AS opens_on_day, bool_and(content_id IS NOT NULL) AS linked
FROM public.bot_knowledge WHERE source = 'video'
GROUP BY title ORDER BY min(unlock_day), title;
